![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

The helper functions `readEvidenceAvailabilityStatus`, `readMethodDiagnosticPosture`, and `readQuestionAvailability` access properties on the `context` object directly. If `context` is passed as `null`, default parameters (like `context = {}`) will not prevent a `TypeError` because default parameters only apply to `undefined`. To defensively handle nullish inputs, ensure these normalization functions fall back to an empty object before property reads (e.g., using `const ctx = context || {}`), and include regression test coverage for null or default states.

```javascript
function readEvidenceAvailabilityStatus(context) {
  const ctx = context || {};
  const rawStatus = normalizeString(
    ctx.evidence_availability_status
      ?? ctx.evidenceAvailabilityStatus
      ?? ctx.evidence_basis?.evidence_availability_status
      ?? ctx.evidenceBasis?.evidenceAvailabilityStatus,
  );
  return EVIDENCE_AVAILABILITY_STATUSES.includes(rawStatus) ? rawStatus : 'not_supplied';
}

function readMethodDiagnosticPosture(context) {
  const ctx = context || {};
  return normalizeString(
    ctx.method_diagnostic_posture
      ?? ctx.methodDiagnosticPosture
      ?? ctx.evidence_basis?.method_diagnostic_posture
      ?? ctx.evidenceBasis?.methodDiagnosticPosture,
  );
}

function readQuestionAvailability(context) {
  const ctx = context || {};
  return normalizeString(
    ctx.question_availability
      ?? ctx.questionAvailability
      ?? ctx.evidence_basis?.question_availability
      ?? ctx.evidenceBasis?.questionAvailability,
    'unknown',
  );
}
